// ARC shared error handler. A shared workflow failed: say so to ARC, in ARC's words.
// Only a category, the failed node's name and an HTTP status leave n8n, never the
// error's text, which can hold anything a provider said. ARC decides the outcome.
const HANDLER = { runner_key: 'arc-runner-error-handler-v1', workflow_version: '1.0.0' };
const CATEGORIES = ['provider_timeout', 'provider_rate_limited', 'provider_auth_failed', 'provider_unreachable', 'provider_error', 'validation_failed', 'unsupported_capability', 'ambiguous_result', 'n8n_internal', 'unexpected_exception'];
// a failure here happened after the module step: its outcome is unknown, not refused.
const AFTER_EFFECT = ['Prepare callback', 'Hash callback', 'Sign callback', 'Send callback'];

const trigger = $('Workflow failed').first().json;
const execution = trigger.execution;
// a trigger that failed before an execution existed ran no job: there is nothing to report.
if (!execution || execution.id === undefined || execution.id === null || !trigger.workflow || trigger.workflow.id === undefined) return [];

const error = execution.error || {};
const message = String(error.message || '');
const code = Number.parseInt(String(error.httpCode ?? ''), 10);
const status = Number.isInteger(code) && code >= 100 && code <= 599 ? code : null;
const node = typeof error.node?.name === 'string' && error.node.name ? error.node.name
  : typeof execution.lastNodeExecuted === 'string' && execution.lastNodeExecuted ? execution.lastNodeExecuted : null;

function categorise() {
  const deliberate = /^arc:([a-z_]+)/.exec(message);
  if (deliberate && CATEGORIES.includes(deliberate[1])) return deliberate[1];
  if (node && AFTER_EFFECT.includes(node)) return 'ambiguous_result';
  if (status === 429) return 'provider_rate_limited';
  if (status === 401 || status === 403) return 'provider_auth_failed';
  if (status === 408 || status === 504) return 'provider_timeout';
  if (status !== null && status >= 500) return 'provider_error';
  if (status !== null && status >= 400) return 'validation_failed';
  if (/ETIMEDOUT|ESOCKETTIMEDOUT|ECONNABORTED|timed out|timeout/i.test(message)) return 'provider_timeout';
  if (/ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH/.test(message)) return 'provider_unreachable';
  if (/ECONNRESET|EPIPE|socket hang up/i.test(message)) return 'ambiguous_result';
  if (!node || /^Workflow(Operation|Activation)Error$/.test(String(error.name || ''))) return 'n8n_internal';
  return 'unexpected_exception';
}

const now = Math.floor(Date.now() / 1000);
const report = {
  contract_version: 1,
  n8n_execution_id: String(execution.id),
  n8n_workflow_id: String(trigger.workflow.id),
  error_category: categorise(),
  failed_node: node ? node.slice(0, 100) : null,
  http_status: status,
  reported_at: new Date().toISOString(),
  handler: HANDLER,
};
return [{ json: {
  body: JSON.stringify(report),
  claims: { aud: 'arc-runner-bridge', purpose: 'failure', iat: now, exp: now + 120, jti: `arc-n8n-${$execution.id}-failure` },
} }];
